import re,glob,os,sys,json
sys.path.insert(0,'/tmp/gr')
from tok import strip_comments, envs, STMT
allproof=0; proofok=0; attributed=0; orphan=[]; optarg=[]
stmt_pins=set(); stmt_nodes=0
proofok_unattributed=[]
for fn in sorted(glob.glob('*.tex')):
    raw=open(fn).read(); t=strip_comments(raw); E=envs(t); base=os.path.basename(fn)
    top=[d for d in E if d['depth']==0]
    for idx,d in enumerate(top):
        if d['env']=='proof':
            allproof+=1
            b=t[d['bend']:d['estart']]
            if re.match(r'\s*\[',b): optarg.append((base,raw[:d['bstart']].count('\n')+1, b[:70].replace('\n',' ')))
            if '\\leanok' in b:
                proofok+=1
                prev = top[idx-1] if idx>0 else None
                if prev is None or prev['env'] not in STMT:
                    orphan.append((base,raw[:d['bstart']].count('\n')+1, prev['env'] if prev else None))
                else:
                    pb=t[prev['bend']:prev['estart']]
                    if re.search(r'\\lean\{',pb) and re.search(r'\\label\{',pb): attributed+=1
                    else: proofok_unattributed.append((base,raw[:d['bstart']].count('\n')+1,
                          'has_lean' if '\\lean{' in pb else 'NO_lean', 'has_label' if '\\label{' in pb else 'NO_label'))
        if d['env'] in STMT:
            body=t[d['bend']:d['estart']]
            if '\\leanok' in body:
                stmt_nodes+=1
                for g in re.findall(r'\\lean\{([^}]*)\}',body):
                    for x in g.split(','):
                        if x.strip(): stmt_pins.add(x.strip())
print('top-level proof envs:',allproof)
print('top-level proof envs carrying leanok:',proofok)
print('  of those attributed to a preceding stmt with BOTH \\lean and \\label:',attributed)
print('  ORPHAN (preceding top env not a statement):',len(orphan), orphan[:10])
print('  preceding stmt lacks lean or label:',len(proofok_unattributed), proofok_unattributed[:6])
print('proof envs with an optional [..] argument:',len(optarg), optarg[:6])
print()
print('statement-level leanok nodes:',stmt_nodes,'  distinct statement-level pins:',len(stmt_pins))
open('/tmp/gr/stmt_pins.txt','w').write('\n'.join(sorted(stmt_pins))+'\n')
